(() => {
  'use strict';
  const KEY='ntmcs_state_v2';
  const ACCOUNT_KEY='ntmcs_account_v2';
  const DARK_KEY='ntmcs_dark_v2';
  const AUDIT_KEY='ntmcs_audit_v2';
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const clone=o=>JSON.parse(JSON.stringify(o));
  const now=()=>new Date().toLocaleString('vi-VN');
  const uid=(table)=>{ const arr=DB[table]||[]; const key={Topic:'topic_id',Topic_Member:'member_id',Topic_Estimate:'estimate_id',Topic_Evaluation:'evaluation_id',Evaluation_Criteria_Score:'evaluation_id',Asset:'asset_id',Asset_Request:'request_id',Fieldwork_Task:'task_id',Notification:'notification_id',Desk:'desk_id',Category:'category_id',User:'user_id',Criteria_Config:'criteria_id',Desk_Quota:'quota_id',Request_Deadline_Extension:'request_id'}[table]; return (arr.reduce((m,x)=>Math.max(m,Number(x[key])||0),0)+1); };
  let DB=loadDB();
  let AUDIT=load(AUDIT_KEY,[]);
  let accountId=Number(localStorage.getItem(ACCOUNT_KEY))||1;
  let page=location.hash.replace('#','')||'dashboard';
  let filters={topics:'',topicStatus:'',requests:'',requestStatus:'',tasks:'',taskStatus:'',users:'',assets:'',notifications:''};

  function load(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}}
  function loadDB(){ const saved=load(KEY,null); return saved&&saved.User&&saved.Topic ? saved : clone(window.NTMCS_SEED); }
  function persist(){localStorage.setItem(KEY,JSON.stringify(DB));localStorage.setItem(ACCOUNT_KEY,String(accountId));localStorage.setItem(AUDIT_KEY,JSON.stringify(AUDIT.slice(0,500)));}
  function user(id=accountId){return DB.User.find(x=>x.user_id===Number(id))||DB.User[0]}
  function role(){return window.NTMCS.roles[user().role]||{label:user().role,short:'?'}}
  function find(table,id,key){key=key||({Topic:'topic_id',User:'user_id',Desk:'desk_id',Category:'category_id',Asset:'asset_id',Asset_Request:'request_id',Fieldwork_Task:'task_id',Topic_Evaluation:'evaluation_id',Notification:'notification_id',Request_Deadline_Extension:'request_id'}[table]);return DB[table].find(x=>Number(x[key])===Number(id))}
  function topic(id){return find('Topic',id)}
  function desk(id){return find('Desk',id)}
  function cat(id){return find('Category',id)}
  function userName(id){return user(id)?.full_name||'—'}
  function label(s){return window.NTMCS.statuses[s]||s||'—'}
  function badge(s){return `<span class="badge b-${String(s).toLowerCase()}">${esc(label(s))}</span>`}
  function money(n){return new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(Number(n)||0)}
  function date(v){return v?new Date(v).toLocaleDateString('vi-VN'):'—'}
  function dt(v){return v?new Date(v).toLocaleString('vi-VN'):'—'}
  function can(action){const r=user().role;const p={
    REPORTER:['topic.create','topic.editOwn','topic.submit','request.create','task.own','extension.create','notification.read'],
    DESK_EDITOR:['topic.view','topic.reviewDesk','evaluation.create','topic.team','topic.estimate','request.view','task.view','extension.review','notification.read'],
    EXECUTIVE_EDITOR:['topic.view','topic.reviewExecutive','evaluation.create','topic.team','topic.estimate','request.view','task.view','extension.review','notification.read'],
    LOGISTICS_COORDINATOR:['asset.manage','asset.requestReview','request.view','notification.read'],
    BUSINESS_ADMINISTRATOR:['quota.manage','topic.view','report.view','notification.read'],
    SYSTEM_ADMINISTRATOR:['all'],
    FIELDWORK_COORDINATOR:['task.manage','topic.view','request.view','notification.read','topic.team']
  };return p[r]?.includes('all')||p[r]?.includes(action)}
  function audit(action,entity,id,result='SUCCESS',detail=''){AUDIT.unshift({at:now(),actor:user().full_name,role:user().role,action,entity,entity_id:id,result,detail});persist()}
  function notify(targetUserId,topicId,message){DB.Notification.unshift({notification_id:uid('Notification'),user_id:Number(targetUserId),topic_id:topicId||null,message,is_read:0});}
  function toast(msg,type='success'){const r=document.getElementById('toast-root');const d=document.createElement('div');d.className='toast '+type;d.innerHTML=`<b>${type==='success'?'✓':type==='error'?'×':'!'}</b><span>${esc(msg)}</span>`;r.appendChild(d);setTimeout(()=>d.remove(),3200)}
  function modal(title,body,actions=''){document.getElementById('modal-root')?.remove();const d=document.createElement('div');d.id='modal-root';d.className='modal-backdrop';d.innerHTML=`<div class="modal"><div class="modal-head"><div><div class="eyebrow">NTMCS</div><h2>${title}</h2></div><button class="icon-btn" data-close>×</button></div><div class="modal-body">${body}</div><div class="modal-foot">${actions||'<button class="btn" data-close>Đóng</button>'}</div></div>`;document.body.appendChild(d);d.addEventListener('click',e=>{if(e.target===d||e.target.closest('[data-close]'))d.remove()});return d.querySelector('.modal')}
  function formField(labelText,name,value='',type='text',attrs=''){return `<label class="field"><span>${labelText}</span><input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`}
  function selectField(labelText,name,options,value=''){return `<label class="field"><span>${labelText}</span><select name="${name}">${options.map(o=>`<option value="${esc(o[0])}" ${String(o[0])===String(value)?'selected':''}>${esc(o[1])}</option>`).join('')}</select></label>`}
  function pageHead(title,sub,actions=''){return `<div class="page-head"><div><div class="eyebrow">NTMCS / ${esc(role().label)}</div><h1>${title}</h1><p>${sub}</p></div><div class="page-actions">${actions}</div></div>`}
  function stat(title,value,sub,icon){return `<div class="stat"><div class="stat-icon">${icon}</div><div><span>${title}</span><strong>${value}</strong><small>${sub}</small></div></div>`}
  function table(cols,rows,empty='Không có dữ liệu'){return `<div class="table-scroll"><table><thead><tr>${cols.map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${cols.length}" class="empty">${empty}</td></tr>`}</tbody></table></div>`}
  function nav(){
    const groups=[['TỔNG QUAN',[['dashboard','⌂','Dashboard'],['notifications','●','Thông báo']]],['ĐỀ TÀI',[['topics','◆','Đề tài'],['evaluations','✓','Đánh giá / phê duyệt'],['extensions','↗','Gia hạn deadline']]],['TÁC NGHIỆP',[['members','◎','Ekip đề tài'],['estimates','₫','Dự toán'],['tasks','☑','Fieldwork Task'],['assets','▣','Tài sản'],['assetRequests','⇄','Yêu cầu tài sản']]],['QUẢN TRỊ NGHIỆP VỤ',[['quotas','▥','Desk Quota'],['users','♙','User'],['master','▤','Master Data'],['audit','≡','Audit Log']]],['HỆ THỐNG',[['account','⇆','Account / chuyển tài khoản'],['settings','⚙','Cài đặt']]]];
    return groups.map(g=>`<div class="nav-group"><div class="nav-label">${g[0]}</div>${g[1].map(x=>`<button class="nav-item ${page===x[0]?'active':''}" data-page="${x[0]}"><i>${x[1]}</i><span>${x[2]}</span></button>`).join('')}</div>`).join('')
  }
  function shell(content){const u=user();const unread=DB.Notification.filter(n=>n.user_id===u.user_id&&!n.is_read).length;return `<div class="app"><aside id="sidebar"><div class="brand"><div class="brand-logo">N</div><div><b>NTMCS</b><small>Newsroom Topic Management</small></div></div><nav>${nav()}</nav><div class="sidebar-bottom"><span class="demo">LOCAL DEMO</span><small>SQL schema → JS state</small></div></aside><section class="main"><header class="topbar"><button class="icon-btn mobile-menu" data-menu>☰</button><button class="search" data-search>⌕ <span>Tìm kiếm nhanh</span><kbd>Ctrl K</kbd></button><button class="icon-btn notif" data-page="notifications">🔔${unread?`<em>${unread}</em>`:''}</button><button class="account-chip" data-page="account"><span class="avatar">${role().short}</span><span><b>${esc(u.full_name)}</b><small>${esc(role().label)}</small></span><span>⌄</span></button></header><main>${content}</main></section></div>`}

  function dashboard(){
    const counts={draft:DB.Topic.filter(x=>x.status==='DRAFT').length,pending:DB.Topic.filter(x=>['SUBMITTED','PENDING_EXECUTIVE_APPROVAL','REVISION_REQUESTED'].includes(x.status)).length,active:DB.Topic.filter(x=>x.status==='IN_PROGRESS').length,ready:DB.Topic.filter(x=>x.status==='ACCEPTED_READY_FOR_CMS').length};
    const myTopics=DB.Topic.filter(x=>x.author_user_id===user().user_id).slice(0,5);
    const req=DB.Asset_Request.filter(x=>x.status==='PENDING').length;
    return pageHead('Dashboard','Tổng quan trực tiếp từ các collection mô phỏng 15 bảng SQL',`<button class="btn primary" data-action="new-topic">＋ Tạo đề tài</button>`)+
      `<div class="stats">${stat('Đề tài chờ xử lý',counts.pending,'Approval workflow','◆')}${stat('Đang tác nghiệp',counts.active,'Topic IN_PROGRESS','◎')}${stat('Asset request chờ',req,'Liên phòng / tài sản','⇄')}${stat('Sẵn sàng CMS',counts.ready,'Topic ACCEPTED_READY_FOR_CMS','✓')}</div>
      <div class="grid2"><section class="card"><div class="card-title"><h2>Lifecycle của Topic</h2><button class="link" data-page="topics">Mở danh sách →</button></div><div class="flow">${['DRAFT','SUBMITTED','REVISION_REQUESTED','PENDING_EXECUTIVE_APPROVAL','APPROVED','IN_PROGRESS','DELIVERED','ACCEPTED_READY_FOR_CMS'].map(s=>`<div><span>${esc(label(s))}</span><b>${DB.Topic.filter(x=>x.status===s).length}</b></div>`).join('')}</div></section><section class="card"><div class="card-title"><h2>Topic của tài khoản hiện tại</h2><button class="link" data-page="topics">Xem tất cả →</button></div>${table(['Mã','Đề tài','Trạng thái'],myTopics.map(t=>`<tr><td>${t.topic_code||'—'}</td><td><button class="row-link" data-topic="${t.topic_id}">${esc(t.title)}</button></td><td>${badge(t.status)}</td></tr>`).join(''))}</section></div>
      <div class="grid3"><section class="card"><h2>Quyền actor hiện tại</h2><div class="permission-box">${permissionsFor(user().role).map(x=>`<span>✓ ${x}</span>`).join('')}</div></section><section class="card"><h2>DB coverage</h2><div class="db-counters">${Object.keys(DB).map(k=>`<div><b>${DB[k].length}</b><span>${k}</span></div>`).join('')}</div></section><section class="card"><h2>Quick switch</h2><p>Đổi account ngay lập tức, không đăng nhập. Dữ liệu và quyền được tính lại theo User.role.</p><button class="btn primary full" data-page="account">Chuyển tài khoản</button></section></div>`;
  }
  function permissionsFor(r){const m={REPORTER:['Tạo/sửa đề tài của mình','Gửi đề tài','Gửi yêu cầu tài sản','Quản lý task được giao'],DESK_EDITOR:['Review phòng ban','Chấm tiêu chí','Phân công ekip','Duyệt gia hạn'],EXECUTIVE_EDITOR:['Duyệt cấp Tổng biên tập','Từ chối / yêu cầu sửa','Xem toàn bộ đề tài'],LOGISTICS_COORDINATOR:['Quản lý Asset','Duyệt Asset Request'],BUSINESS_ADMINISTRATOR:['Quản lý Desk Quota','Báo cáo nghiệp vụ'],SYSTEM_ADMINISTRATOR:['Toàn quyền demo'],FIELDWORK_COORDINATOR:['Quản lý Fieldwork Task','Điều phối tác nghiệp']};return m[r]||[]}

  function topics(){const q=filters.topics.toLowerCase();let arr=DB.Topic.filter(t=>(!q||`${t.title} ${t.topic_code||''}`.toLowerCase().includes(q))&&(!filters.topicStatus||t.status===filters.topicStatus));return pageHead('Đề tài','Bảng Topic — khớp trực tiếp với Topic table',can('topic.create')?`<button class="btn primary" data-action="new-topic">＋ Tạo đề tài</button>`:'')+`<div class="filterbar"><input id="topic-q" value="${esc(filters.topics)}" placeholder="⌕ Tìm mã, tiêu đề..."><select id="topic-status"><option value="">Tất cả trạng thái</option>${['DRAFT','SUBMITTED','REVISION_REQUESTED','PENDING_EXECUTIVE_APPROVAL','APPROVED','IN_PROGRESS','DELIVERED','ACCEPTED_READY_FOR_CMS','REJECTED','ABORTED'].map(s=>`<option value="${s}" ${filters.topicStatus===s?'selected':''}>${label(s)}</option>`).join('')}</select><button class="btn" data-clear="topics">Xóa lọc</button></div>`+table(['ID','Code','Tiêu đề','Desk / Category','Author','Deadline','Status','Action'],arr.map(t=>`<tr><td>#${t.topic_id}</td><td><b>${t.topic_code||'—'}</b></td><td><button class="row-link" data-topic="${t.topic_id}">${esc(t.title)}</button><small>${esc(t.angle||'')}</small></td><td>${esc(desk(cat(t.category_id)?.desk_id)?.desk_name||'')}<small>${esc(cat(t.category_id)?.category_name||'')}</small></td><td>${esc(userName(t.author_user_id))}</td><td>${date(t.deadline)}</td><td>${badge(t.status)}</td><td><button class="btn sm" data-topic="${t.topic_id}">Mở</button></td></tr>`).join(''));
  }
  function topicDetail(id){const t=topic(id);if(!t)return topics();const author=user(t.author_user_id);const members=DB.Topic_Member.filter(m=>m.topic_id===id);const estimates=DB.Topic_Estimate.filter(e=>e.topic_id===id);const evals=DB.Topic_Evaluation.filter(e=>e.topic_id===id);const reqs=DB.Asset_Request.filter(r=>r.topic_id===id);const tasks=DB.Fieldwork_Task.filter(x=>x.topic_id===id);const ext=DB.Request_Deadline_Extension.filter(x=>x.topic_id===id);return pageHead(t.title,`Topic #${t.topic_id} · ${t.topic_code||'chưa cấp code'}`,`<button class="btn" data-page="topics">← Danh sách</button>`)+`<div class="detail-grid"><section class="card hero-card"><div class="detail-title"><div><div class="eyebrow">${esc(t.topic_code||'DRAFT')}</div><h2>${esc(t.title)}</h2><p>${esc(t.angle||'Chưa có angle')}</p></div>${badge(t.status)}</div><div class="meta-grid"><div><span>Author</span><b>${esc(author.full_name)}</b></div><div><span>Category</span><b>${esc(cat(t.category_id)?.category_name)}</b></div><div><span>Desk</span><b>${esc(desk(cat(t.category_id)?.desk_id)?.desk_name)}</b></div><div><span>Deadline</span><b>${date(t.deadline)}</b></div></div><div class="action-row">${topicActions(t)}</div></section><section class="card"><h2>Workflow</h2>${workflow(t)}</section></div><div class="grid2"><section class="card"><div class="card-title"><h2>Topic_Member (${members.length})</h2><button class="btn sm" data-action="add-member" data-topic-id="${id}">＋ Thêm</button></div>${table(['User','Vai trò'],members.map(m=>`<tr><td>${esc(userName(m.user_id))}</td><td>${esc(window.NTMCS.teamRoles[m.role_in_team])}</td></tr>`).join(''))}</section><section class="card"><div class="card-title"><h2>Topic_Estimate</h2><button class="btn sm" data-action="add-estimate" data-topic-id="${id}">＋ Thêm</button></div>${table(['Hạng mục','Số tiền'],estimates.map(e=>`<tr><td>${esc(e.cost_item)}</td><td>${money(e.amount)}</td></tr>`).join(''), 'Chưa có dự toán')}</section></div><div class="grid2"><section class="card"><h2>Asset_Request</h2>${table(['#','Asset','Requester','Thời gian','Status'],reqs.map(r=>`<tr><td>#${r.request_id}</td><td>${esc(find('Asset',r.asset_id)?.asset_name)}</td><td>${esc(userName(r.requester_user_id))}</td><td>${dt(r.start_time)} → ${dt(r.end_time)}</td><td>${badge(r.status)}</td></tr>`).join(''),'Chưa có yêu cầu')}</section><section class="card"><h2>Fieldwork_Task</h2>${table(['#','Task','Assignee','Status'],tasks.map(x=>`<tr><td>#${x.task_id}</td><td>${esc(x.description)}</td><td>${esc(userName(x.assignee_user_id))}</td><td>${badge(x.task_status)}</td></tr>`).join(''),'Chưa có task')}</section></div><div class="grid2"><section class="card"><h2>Topic_Evaluation</h2>${table(['Stage','Evaluator','Decision','Comment'],evals.map(e=>`<tr><td>${label(e.evaluation_stage)}</td><td>${esc(userName(e.evaluator_user_id))}</td><td>${badge(e.decision)}</td><td>${esc(e.comments||'')}</td></tr>`).join(''),'Chưa có đánh giá')}</section><section class="card"><h2>Request_Deadline_Extension</h2>${table(['#','Requester','Current','Requested','Status'],ext.map(e=>`<tr><td>#${e.request_id}</td><td>${esc(userName(e.requested_by_user_id))}</td><td>${date(e.current_deadline)}</td><td>${date(e.requested_deadline)}</td><td>${badge(e.status)}</td></tr>`).join(''),'Chưa có yêu cầu gia hạn')}</section></div>`}
  function workflow(t){const steps=['DRAFT','SUBMITTED','REVISION_REQUESTED','PENDING_EXECUTIVE_APPROVAL','APPROVED','IN_PROGRESS','DELIVERED','ACCEPTED_READY_FOR_CMS'];const rank={DRAFT:0,SUBMITTED:1,REVISION_REQUESTED:1.5,PENDING_EXECUTIVE_APPROVAL:2,APPROVED:3,IN_PROGRESS:4,DELIVERED:5,ACCEPTED_READY_FOR_CMS:6,REJECTED:-1,ABORTED:-1};return `<div class="timeline">${steps.map((s,i)=>`<div class="step ${rank[t.status]>=i?'done':''} ${t.status===s?'current':''}"><span>${i+1}</span><div><b>${label(s)}</b><small>${s}</small></div></div>`).join('')}</div>`}
  function topicActions(t){const a=[];if(can('topic.editOwn')&&t.author_user_id===user().user_id&&['DRAFT','REVISION_REQUESTED'].includes(t.status))a.push(`<button class="btn" data-action="edit-topic" data-id="${t.topic_id}">Sửa</button>`);if(can('topic.submit')&&t.author_user_id===user().user_id&&['DRAFT','REVISION_REQUESTED'].includes(t.status))a.push(`<button class="btn primary" data-action="submit-topic" data-id="${t.topic_id}">Gửi đề tài</button>`);if(can('topic.reviewDesk')&&t.status==='SUBMITTED')a.push(`<button class="btn success" data-action="desk-approve" data-id="${t.topic_id}">✓ Duyệt phòng</button><button class="btn warning" data-action="request-revision" data-id="${t.topic_id}">↩ Yêu cầu sửa</button><button class="btn danger" data-action="reject-topic" data-id="${t.topic_id}">Từ chối</button>`);if(can('topic.reviewExecutive')&&t.status==='PENDING_EXECUTIVE_APPROVAL')a.push(`<button class="btn success" data-action="exec-approve" data-id="${t.topic_id}">✓ TBT duyệt</button><button class="btn warning" data-action="request-revision" data-id="${t.topic_id}">↩ Yêu cầu sửa</button><button class="btn danger" data-action="reject-topic" data-id="${t.topic_id}">Từ chối</button>`);if(t.status==='APPROVED'&&(can('topic.team')||can('task.manage')))a.push(`<button class="btn primary" data-action="start-topic" data-id="${t.topic_id}">▶ Bắt đầu tác nghiệp</button>`);if(t.status==='IN_PROGRESS'&&can('task.manage'))a.push(`<button class="btn" data-action="deliver-topic" data-id="${t.topic_id}">Bàn giao</button>`);if(t.status==='DELIVERED'&&can('topic.reviewExecutive'))a.push(`<button class="btn success" data-action="accept-topic" data-id="${t.topic_id}">✓ Chấp nhận / sẵn sàng CMS</button>`);if(can('request.create')&&['APPROVED','IN_PROGRESS'].includes(t.status))a.push(`<button class="btn" data-action="new-request" data-topic-id="${t.topic_id}">＋ Yêu cầu tài sản</button>`);if(can('task.manage')&&['APPROVED','IN_PROGRESS'].includes(t.status))a.push(`<button class="btn" data-action="new-task" data-topic-id="${t.topic_id}">＋ Fieldwork Task</button>`);return a.join('')||'<span class="muted">Không có action cho account hiện tại.</span>'}

  function newTopicForm(existing){const t=existing||{title:'',angle:'',deadline:'',category_id:DB.Category[0]?.category_id||1};const modalEl=modal(existing?'Sửa Topic':'Tạo Topic',`<form id="topic-form" class="form-grid">${formField('Tiêu đề','title',t.title,'text','required')}${formField('Angle','angle',t.angle)}${formField('Deadline','deadline',t.deadline,'date')} ${selectField('Category','category_id',DB.Category.map(c=>[c.category_id,c.category_name]),t.category_id)}<div class="field full"><span>Author</span><input value="${esc(user().full_name)}" disabled></div></form>`,`<button class="btn" data-close>Hủy</button><button class="btn primary" data-submit-form="topic-form">Lưu</button>`);modalEl.closest('.modal-backdrop').querySelector('[data-submit-form]').onclick=()=>{const f=new FormData(document.getElementById('topic-form'));const data={title:f.get('title').trim(),angle:f.get('angle').trim(),deadline:f.get('deadline')||null,category_id:Number(f.get('category_id'))};if(!data.title)return toast('Tiêu đề bắt buộc','error');if(existing){Object.assign(existing,data);audit('UPDATE','Topic',existing.topic_id);toast('Đã cập nhật Topic')}else{const id=uid('Topic');DB.Topic.push({topic_id:id,topic_code:null,...data,status:'DRAFT',author_user_id:user().user_id});audit('CREATE','Topic',id);toast('Đã tạo Topic #'+id)}persist();modalEl.closest('.modal-backdrop').remove();render()}}

  function evaluations(){const arr=DB.Topic_Evaluation;return pageHead('Đánh giá / phê duyệt','Topic_Evaluation + Evaluation_Criteria_Score',`<button class="btn primary" data-action="new-evaluation">＋ Tạo đánh giá</button>`)+table(['ID','Topic','Stage','Evaluator','Decision','Điểm TB','Comment'],arr.map(e=>{const scores=DB.Evaluation_Criteria_Score.filter(s=>s.evaluation_id===e.evaluation_id);const avg=scores.length?(scores.reduce((a,b)=>a+b.score,0)/scores.length).toFixed(2):'—';return `<tr><td>#${e.evaluation_id}</td><td><button class="row-link" data-topic="${e.topic_id}">${esc(topic(e.topic_id)?.title)}</button></td><td>${label(e.evaluation_stage)}</td><td>${esc(userName(e.evaluator_user_id))}</td><td>${badge(e.decision)}</td><td>${avg}/10</td><td>${esc(e.comments||'')}</td></tr>`}).join(''))}
  function evaluationForm(){const topics=DB.Topic.filter(t=>!['REJECTED','ABORTED'].includes(t.status));const modalEl=modal('Tạo Topic Evaluation',`<form id="eval-form" class="form-grid">${selectField('Topic','topic_id',topics.map(t=>[t.topic_id,`#${t.topic_id} — ${t.title}`]))}${selectField('Stage','evaluation_stage',[['DESK_REVIEW','Desk Review'],['EXECUTIVE_APPROVAL','Executive Approval']])}${selectField('Decision','decision',[['APPROVED','Approved'],['REJECTED','Rejected'],['REVISION_REQUESTED','Revision Requested'],['ESCALATED','Escalated']])}<div class="field full"><span>Comments</span><textarea name="comments" rows="4"></textarea></div><div class="field full"><span>Điểm tiêu chí (0-10)</span><div class="criteria-grid">${DB.Criteria_Config.map(c=>`<label><span>${esc(c.criteria_name)} (${c.weight_percent}%)</span><input name="score_${c.criteria_id}" type="number" min="0" max="10" step="0.5" value="0"></label>`).join('')}</div></div></form>`,`<button class="btn" data-close>Hủy</button><button class="btn primary" data-submit-form="eval-form">Lưu đánh giá</button>`);modalEl.closest('.modal-backdrop').querySelector('[data-submit-form]').onclick=()=>{const f=new FormData(document.getElementById('eval-form'));const id=uid('Topic_Evaluation');const tid=Number(f.get('topic_id'));DB.Topic_Evaluation.push({evaluation_id:id,topic_id:tid,evaluator_user_id:user().user_id,evaluation_stage:f.get('evaluation_stage'),decision:f.get('decision'),comments:f.get('comments')});DB.Criteria_Config.forEach(c=>DB.Evaluation_Criteria_Score.push({evaluation_id:id,criteria_id:c.criteria_id,score:Number(f.get('score_'+c.criteria_id)||0)}));audit('CREATE','Topic_Evaluation',id);persist();modalEl.closest('.modal-backdrop').remove();toast('Đã tạo đánh giá');render()}}

  function members(){return pageHead('Ekip đề tài','Topic_Member — phân công đúng role_in_team',`<button class="btn primary" data-action="add-member">＋ Phân công</button>`)+table(['ID','Topic','User','Role in team'],DB.Topic_Member.map(m=>`<tr><td>#${m.member_id}</td><td>${esc(topic(m.topic_id)?.title)}</td><td>${esc(userName(m.user_id))}</td><td>${esc(window.NTMCS.teamRoles[m.role_in_team])}</td></tr>`).join(''))}
  function memberForm(topicId){const modalEl=modal('Phân công Topic Member',`<form id="member-form" class="form-grid">${selectField('Topic','topic_id',DB.Topic.map(t=>[t.topic_id,t.title]),topicId)}${selectField('User','user_id',DB.User.filter(u=>u.role!=='SYSTEM_ADMINISTRATOR').map(u=>[u.user_id,u.full_name+' · '+u.role]))}${selectField('Role in team','role_in_team',Object.entries(window.NTMCS.teamRoles))}</form>`,`<button class="btn" data-close>Hủy</button><button class="btn primary" data-submit-form="member-form">Lưu</button>`);modalEl.closest('.modal-backdrop').querySelector('[data-submit-form]').onclick=()=>{const f=new FormData(document.getElementById('member-form'));const tid=Number(f.get('topic_id')),uid2=Number(f.get('user_id'));if(DB.Topic_Member.some(x=>x.topic_id===tid&&x.user_id===uid2))return toast('User này đã có trong ekip','error');const id=uid('Topic_Member');DB.Topic_Member.push({member_id:id,topic_id:tid,user_id:uid2,role_in_team:f.get('role_in_team')});audit('CREATE','Topic_Member',id);persist();modalEl.closest('.modal-backdrop').remove();toast('Đã phân công');render()}}
  function estimates(){return pageHead('Dự toán','Topic_Estimate — chi phí dự kiến theo đề tài',`<button class="btn primary" data-action="add-estimate">＋ Thêm khoản chi</button>`)+table(['ID','Topic','Hạng mục','Amount'],DB.Topic_Estimate.map(e=>`<tr><td>#${e.estimate_id}</td><td>${esc(topic(e.topic_id)?.title)}</td><td>${esc(e.cost_item)}</td><td><b>${money(e.amount)}</b></td></tr>`).join(''))}
  function estimateForm(topicId){const m=modal('Thêm Topic Estimate',`<form id="estimate-form" class="form-grid">${selectField('Topic','topic_id',DB.Topic.map(t=>[t.topic_id,t.title]),topicId)}${formField('Cost item','cost_item','','text','required')}${formField('Amount','amount','0','number','min="0" step="1000" required')}</form>`,`<button class="btn" data-close>Hủy</button><button class="btn primary" data-submit-form="estimate-form">Lưu</button>`);m.closest('.modal-backdrop').querySelector('[data-submit-form]').onclick=()=>{const f=new FormData(document.getElementById('estimate-form'));const id=uid('Topic_Estimate');DB.Topic_Estimate.push({estimate_id:id,topic_id:Number(f.get('topic_id')),cost_item:f.get('cost_item'),amount:Number(f.get('amount'))});audit('CREATE','Topic_Estimate',id);persist();m.closest('.modal-backdrop').remove();toast('Đã thêm dự toán');render()}}

  function assets(){return pageHead('Tài sản','Asset — tài sản được yêu cầu/điều phối',`<button class="btn primary" data-action="new-asset">＋ Thêm Asset</button>`)+table(['ID','Tên tài sản','Trạng thái','Đang có request'],DB.Asset.map(a=>`<tr><td>#${a.asset_id}</td><td><b>${esc(a.asset_name)}</b></td><td>${badge(a.asset_status)}</td><td>${DB.Asset_Request.filter(r=>r.asset_id===a.asset_id&&['PENDING','APPROVED','CHECKED_OUT'].includes(r.status)).length}</td></tr>`).join(''))}
  function assetForm(){const m=modal('Tạo Asset',`<form id="asset-form">${formField('Asset name','asset_name','','text','required')}${selectField('Status','asset_status',[['AVAILABLE','AVAILABLE'],['MAINTENANCE','MAINTENANCE']],'AVAILABLE')}</form>`,`<button class="btn" data-close>Hủy</button><button class="btn primary" data-submit-form="asset-form">Lưu</button>`);m.closest('.modal-backdrop').querySelector('[data-submit-form]').onclick=()=>{const f=new FormData(document.getElementById('asset-form'));const id=uid('Asset');DB.Asset.push({asset_id:id,asset_name:f.get('asset_name'),asset_status:f.get('asset_status')});audit('CREATE','Asset',id);persist();m.closest('.modal-backdrop').remove();toast('Đã tạo Asset');render()}}

  function assetRequests(){let arr=DB.Asset_Request.filter(r=>(!filters.requests||`${r.request_id} ${find('Asset',r.asset_id)?.asset_name||''} ${userName(r.requester_user_id)}`.toLowerCase().includes(filters.requests.toLowerCase()))&&(!filters.requestStatus||r.status===filters.requestStatus));return pageHead('Yêu cầu tài sản','Asset_Request — sender/receiver workflow giữa actor',can('request.create')?`<button class="btn primary" data-action="new-request">＋ Tạo yêu cầu</button>`:'')+`<div class="filterbar"><input id="rq-q" value="${esc(filters.requests)}" placeholder="⌕ Tìm request..."><select id="rq-status"><option value="">Tất cả</option>${['PENDING','APPROVED','REJECTED','CHECKED_OUT','RETURNED'].map(s=>`<option value="${s}" ${filters.requestStatus===s?'selected':''}>${label(s)}</option>`).join('')}</select><button class="btn" data-clear="requests">Xóa lọc</button></div>`+table(['ID','Topic','Asset','Requester','Thời gian','Status','Action'],arr.map(r=>`<tr><td>#${r.request_id}</td><td>${esc(topic(r.topic_id)?.title)}</td><td>${esc(find('Asset',r.asset_id)?.asset_name)}</td><td>${esc(userName(r.requester_user_id))}</td><td>${dt(r.start_time)}<small>→ ${dt(r.end_time)}</small></td><td>${badge(r.status)}</td><td>${requestActions(r)}</td></tr>`).join(''))}
  function requestActions(r){const out=[];if(can('asset.requestReview')&&r.status==='PENDING')out.push(`<button class="btn sm success" data-action="request-approve" data-id="${r.request_id}">Duyệt</button><button class="btn sm danger" data-action="request-reject" data-id="${r.request_id}">Từ chối</button>`);if(can('request.create')&&r.requester_user_id===user().user_id&&r.status==='APPROVED')out.push(`<button class="btn sm" data-action="checkout" data-id="${r.request_id}">Nhận tài sản</button>`);if(can('request.create')&&r.requester_user_id===user().user_id&&r.status==='CHECKED_OUT')out.push(`<button class="btn sm" data-action="return-asset" data-id="${r.request_id}">Trả tài sản</button>`);return out.join('')||'<span class="muted">—</span>'}
  function requestForm(topicId){const m=modal('Tạo Asset Request',`<form id="rq-form" class="form-grid">${selectField('Topic','topic_id',DB.Topic.filter(t=>['APPROVED','IN_PROGRESS'].includes(t.status)).map(t=>[t.topic_id,t.title]),topicId)}${selectField('Asset','asset_id',DB.Asset.filter(a=>a.asset_status==='AVAILABLE').map(a=>[a.asset_id,a.asset_name]))}${formField('Start time','start_time','','datetime-local','required')}${formField('End time','end_time','','datetime-local','required')}</form>`,`<button class="btn" data-close>Hủy</button><button class="btn primary" data-submit-form="rq-form">Gửi yêu cầu</button>`);m.closest('.modal-backdrop').querySelector('[data-submit-form]').onclick=()=>{const f=new FormData(document.getElementById('rq-form'));const st=f.get('start_time'),et=f.get('end_time');if(!st||!et||new Date(et)<=new Date(st))return toast('Thời gian không hợp lệ','error');const id=uid('Asset_Request');const aid=Number(f.get('asset_id'));DB.Asset_Request.push({request_id:id,topic_id:Number(f.get('topic_id')),asset_id:aid,requester_user_id:user().user_id,start_time:st,end_time:et,status:'PENDING'});const receiver=DB.User.find(u=>u.role==='LOGISTICS_COORDINATOR');if(receiver)notify(receiver.user_id,Number(f.get('topic_id')),`Asset request #${id} từ ${user().full_name} đang chờ xử lý.`);audit('CREATE','Asset_Request',id);persist();m.closest('.modal-backdrop').remove();toast('Đã gửi Asset Request');render()}}

  function tasks(){let arr=DB.Fieldwork_Task.filter(t=>(!filters.tasks||`${t.task_id} ${t.description} ${userName(t.assignee_user_id)}`.toLowerCase().includes(filters.tasks.toLowerCase()))&&(!filters.taskStatus||t.task_status===filters.taskStatus));return pageHead('Fieldwork Task','Fieldwork_Task — công việc phát sinh từ Topic',can('task.manage')||can('task.own')?`<button class="btn primary" data-action="new-task">＋ Tạo task</button>`:'')+`<div class="filterbar"><input id="task-q" value="${esc(filters.tasks)}" placeholder="⌕ Tìm task..."><select id="task-status"><option value="">Tất cả</option>${['TODO','IN_PROGRESS','DONE'].map(s=>`<option value="${s}" ${filters.taskStatus===s?'selected':''}>${label(s)}</option>`).join('')}</select><button class="btn" data-clear="tasks">Xóa lọc</button></div><div class="kanban">${['TODO','IN_PROGRESS','DONE'].map(s=>`<section class="kanban-col"><div class="kanban-head"><b>${label(s)}</b><span>${arr.filter(t=>t.task_status===s).length}</span></div>${arr.filter(t=>t.task_status===s).map(t=>`<article class="task-card"><div class="task-top"><b>#${t.task_id}</b>${badge(t.task_status)}</div><h3>${esc(t.description||'Không mô tả')}</h3><small>${esc(topic(t.topic_id)?.title||'')}</small><div class="task-foot"><span>${esc(userName(t.assignee_user_id))}</span>${taskButtons(t)}</div></article>`).join('')||'<div class="empty-card">Trống</div>'}</section>`).join('')}</div>`}
  function taskButtons(t){if(can('task.manage')||t.assignee_user_id===user().user_id)return `<button class="btn sm" data-action="cycle-task" data-id="${t.task_id}">Đổi trạng thái</button>`;return ''}
  function taskForm(topicId){const m=modal('Tạo Fieldwork Task',`<form id="task-form" class="form-grid">${selectField('Topic','topic_id',DB.Topic.filter(t=>['APPROVED','IN_PROGRESS'].includes(t.status)).map(t=>[t.topic_id,t.title]),topicId)}${selectField('Assignee','assignee_user_id',DB.User.filter(u=>['REPORTER','FIELDWORK_COORDINATOR','DESK_EDITOR'].includes(u.role)).map(u=>[u.user_id,u.full_name+' · '+u.role]))}<div class="field full"><span>Description</span><textarea name="description" rows="4" required></textarea></div></form>`,`<button class="btn" data-close>Hủy</button><button class="btn primary" data-submit-form="task-form">Lưu task</button>`);m.closest('.modal-backdrop').querySelector('[data-submit-form]').onclick=()=>{const f=new FormData(document.getElementById('task-form'));const id=uid('Fieldwork_Task');DB.Fieldwork_Task.push({task_id:id,topic_id:Number(f.get('topic_id')),assignee_user_id:Number(f.get('assignee_user_id')),task_status:'TODO',description:f.get('description')});notify(Number(f.get('assignee_user_id')),Number(f.get('topic_id')),`Bạn được giao Fieldwork Task #${id}.`);audit('CREATE','Fieldwork_Task',id);persist();m.closest('.modal-backdrop').remove();toast('Đã tạo task');render()}}

  function quotas(){return pageHead('Desk Quota','Desk_Quota — hạn mức theo desk và period',can('quota.manage')?`<button class="btn primary" data-action="new-quota">＋ Thêm quota</button>`:'')+table(['ID','Desk','Period','Quota count'],DB.Desk_Quota.map(q=>`<tr><td>#${q.quota_id}</td><td>${esc(desk(q.desk_id)?.desk_name)}</td><td>${esc(q.period)}</td><td><b>${q.quota_count}</b></td></tr>`).join(''))}
  function quotaForm(){const m=modal('Desk Quota',`<form id="quota-form" class="form-grid">${selectField('Desk','desk_id',DB.Desk.map(d=>[d.desk_id,d.desk_name]))}${formField('Period','period','2026-10','','required')}${formField('Quota count','quota_count','10','number','min="0" required')}</form>`,`<button class="btn" data-close>Hủy</button><button class="btn primary" data-submit-form="quota-form">Lưu</button>`);m.closest('.modal-backdrop').querySelector('[data-submit-form]').onclick=()=>{const f=new FormData(document.getElementById('quota-form'));const d=Number(f.get('desk_id')),p=f.get('period');if(DB.Desk_Quota.some(x=>x.desk_id===d&&x.period===p))return toast('Desk + period đã tồn tại','error');const id=uid('Desk_Quota');DB.Desk_Quota.push({quota_id:id,desk_id:d,period:p,quota_count:Number(f.get('quota_count'))});audit('CREATE','Desk_Quota',id);persist();m.closest('.modal-backdrop').remove();toast('Đã lưu quota');render()}}

  function extensions(){return pageHead('Gia hạn deadline','Request_Deadline_Extension — yêu cầu gia hạn gắn với Topic',can('extension.create')?`<button class="btn primary" data-action="new-extension">＋ Xin gia hạn</button>`:'')+table(['ID','Topic','Requester','Current','Requested','Reason','Status','Action'],DB.Request_Deadline_Extension.map(e=>`<tr><td>#${e.request_id}</td><td>${esc(topic(e.topic_id)?.title)}</td><td>${esc(userName(e.requested_by_user_id))}</td><td>${date(e.current_deadline)}</td><td>${date(e.requested_deadline)}</td><td>${esc(e.reason)}</td><td>${badge(e.status)}</td><td>${can('extension.review')&&e.status==='PENDING'?`<button class="btn sm success" data-action="extension-approve" data-id="${e.request_id}">Duyệt</button><button class="btn sm danger" data-action="extension-reject" data-id="${e.request_id}">Từ chối</button>`:'—'}</td></tr>`).join(''))}
  function extensionForm(){const own=DB.Topic.filter(t=>t.author_user_id===user().user_id);const m=modal('Xin gia hạn deadline',`<form id="ext-form" class="form-grid">${selectField('Topic','topic_id',own.map(t=>[t.topic_id,`#${t.topic_id} — ${t.title}`]))}${formField('Requested deadline','requested_deadline','','date','required')}<div class="field full"><span>Reason</span><textarea name="reason" rows="4" required></textarea></div></form>`,`<button class="btn" data-close>Hủy</button><button class="btn primary" data-submit-form="ext-form">Gửi</button>`);m.closest('.modal-backdrop').querySelector('[data-submit-form]').onclick=()=>{const f=new FormData(document.getElementById('ext-form'));const t=topic(Number(f.get('topic_id')));const requested=f.get('requested_deadline');if(!t||new Date(requested)<=new Date(t.deadline))return toast('Deadline mới phải lớn hơn deadline hiện tại','error');const id=uid('Request_Deadline_Extension');DB.Request_Deadline_Extension.push({request_id:id,topic_id:t.topic_id,requested_by_user_id:user().user_id,current_deadline:t.deadline,requested_deadline:requested,reason:f.get('reason'),status:'PENDING'});const approver=DB.User.find(u=>u.role==='DESK_EDITOR');if(approver)notify(approver.user_id,t.topic_id,`Yêu cầu gia hạn #${id} cần xử lý.`);audit('CREATE','Request_Deadline_Extension',id);persist();m.closest('.modal-backdrop').remove();toast('Đã gửi yêu cầu gia hạn');render()}}

  function notifications(){const arr=DB.Notification.filter(n=>n.user_id===user().user_id&&(!filters.notifications||n.message.toLowerCase().includes(filters.notifications.toLowerCase())));return pageHead('Thông báo','Notification table — chỉ hiển thị thông báo của account hiện tại',`<button class="btn" data-action="read-all">Đánh dấu tất cả đã đọc</button>`)+`<div class="filterbar"><input id="notif-q" value="${esc(filters.notifications)}" placeholder="⌕ Tìm thông báo..."></div><div class="notifications">${arr.map(n=>`<article class="notification ${n.is_read?'read':''}" data-notif="${n.notification_id}"><span class="notif-icon">${n.is_read?'✓':'!'}</span><div><b>${esc(n.message)}</b><small>Topic #${n.topic_id||'—'}</small></div>${!n.is_read?`<button class="btn sm" data-action="read-notif" data-id="${n.notification_id}">Đã đọc</button>`:''}</article>`).join('')||'<div class="empty-card">Không có thông báo</div>'}</div>`}

  function users(){return pageHead('User','Bám đúng User table; account switcher dùng trực tiếp các record này',`<button class="btn primary" data-action="new-user">＋ Tạo User</button>`)+`<div class="filterbar"><input id="user-q" value="${esc(filters.users)}" placeholder="⌕ Tìm tên/email..."></div>`+table(['ID','Full name','Email','Role','Desk','Account switch'],DB.User.filter(u=>!filters.users||`${u.full_name} ${u.email}`.toLowerCase().includes(filters.users.toLowerCase())).map(u=>`<tr><td>#${u.user_id}</td><td><b>${esc(u.full_name)}</b></td><td>${esc(u.email)}</td><td>${esc(window.NTMCS.roles[u.role]?.label||u.role)}<small>${u.role}</small></td><td>${esc(desk(u.desk_id)?.desk_name||'—')}</td><td><button class="btn sm" data-switch-user="${u.user_id}">Chuyển sang</button></td></tr>`).join(''))}
  function userForm(){const m=modal('Tạo User',`<form id="user-form" class="form-grid">${formField('Full name','full_name','','text','required')}${formField('Email','email','','email','required')}${selectField('Role','role',Object.entries(window.NTMCS.roles).map(([k,v])=>[k,v.label]))}${selectField('Desk','desk_id',[['','Không gắn desk'],...DB.Desk.map(d=>[d.desk_id,d.desk_name])])}</form>`,`<button class="btn" data-close>Hủy</button><button class="btn primary" data-submit-form="user-form">Lưu</button>`);m.closest('.modal-backdrop').querySelector('[data-submit-form]').onclick=()=>{const f=new FormData(document.getElementById('user-form'));if(DB.User.some(u=>u.email===f.get('email')))return toast('Email đã tồn tại','error');const id=uid('User');DB.User.push({user_id:id,full_name:f.get('full_name'),email:f.get('email'),role:f.get('role'),desk_id:f.get('desk_id')?Number(f.get('desk_id')):null});audit('CREATE','User',id);persist();m.closest('.modal-backdrop').remove();toast('Đã tạo User');render()}}

  function master(){return pageHead('Master Data','Desk, Category và Criteria_Config')+`<div class="grid3"><section class="card"><div class="card-title"><h2>Desk</h2><button class="btn sm" data-action="new-desk">＋</button></div>${table(['ID','Name'],DB.Desk.map(d=>`<tr><td>#${d.desk_id}</td><td>${esc(d.desk_name)}</td></tr>`).join(''))}</section><section class="card"><div class="card-title"><h2>Category</h2><button class="btn sm" data-action="new-category">＋</button></div>${table(['ID','Name','Parent','Desk'],DB.Category.map(c=>`<tr><td>#${c.category_id}</td><td>${esc(c.category_name)}</td><td>${esc(cat(c.parent_category_id)?.category_name||'—')}</td><td>${esc(desk(c.desk_id)?.desk_name)}</td></tr>`).join(''))}</section><section class="card"><div class="card-title"><h2>Criteria_Config</h2><button class="btn sm" data-action="new-criteria">＋</button></div>${table(['ID','Criteria','Weight'],DB.Criteria_Config.map(c=>`<tr><td>#${c.criteria_id}</td><td>${esc(c.criteria_name)}</td><td>${c.weight_percent}%</td></tr>`).join(''))}</section></div>`}
  function simpleMaster(type){const configs={desk:{title:'Desk',fields:[['desk_name','Desk name']],table:'Desk'},category:{title:'Category',fields:[['category_name','Category name']],table:'Category'},criteria:{title:'Criteria Config',fields:[['criteria_name','Criteria name'],['weight_percent','Weight %']]}};const c=configs[type];const m=modal('Thêm '+c.title,`<form id="simple-form">${c.fields.map(f=>formField(f[1],f[0],f[0]==='weight_percent'?'20':'','text','required')).join('')}</form>`,`<button class="btn" data-close>Hủy</button><button class="btn primary" data-submit-form="simple-form">Lưu</button>`);m.closest('.modal-backdrop').querySelector('[data-submit-form]').onclick=()=>{const f=new FormData(document.getElementById('simple-form'));if(type==='desk')DB.Desk.push({desk_id:uid('Desk'),desk_name:f.get('desk_name')});if(type==='category')DB.Category.push({category_id:uid('Category'),category_name:f.get('category_name'),parent_category_id:null,desk_id:DB.Desk[0]?.desk_id});if(type==='criteria')DB.Criteria_Config.push({criteria_id:uid('Criteria_Config'),criteria_name:f.get('criteria_name'),weight_percent:Number(f.get('weight_percent'))});audit('CREATE',c.table,'new');persist();m.closest('.modal-backdrop').remove();toast('Đã thêm '+c.title);render()}}

  function account(){const u=user();return pageHead('Account / chuyển tài khoản','Không cần đăng nhập lại — chọn trực tiếp User record để mô phỏng actor')+`<div class="account-banner"><div class="avatar xl">${role().short}</div><div><div class="eyebrow">CURRENT ACCOUNT</div><h2>${esc(u.full_name)}</h2><p>${esc(u.email)} · <b>${esc(u.role)}</b></p></div></div><div class="switch-grid">${DB.User.map(x=>{const r=window.NTMCS.roles[x.role]||{};const special=x.user_id===3?' · Demo Thư ký quy trình':x.user_id===2?' · Trưởng phòng phòng ban':'';return `<article class="account-card ${x.user_id===u.user_id?'current':''}"><div class="avatar">${esc(r.short||'?')}</div><div><h3>${esc(x.full_name)}</h3><p>${esc(r.label||x.role)}${special}</p><small>${esc(x.email)}</small></div><button class="btn ${x.user_id===u.user_id?'success':'primary'}" data-switch-user="${x.user_id}">${x.user_id===u.user_id?'Đang dùng':'Chuyển sang'}</button></article>`}).join('')}</div><section class="card"><h2>Lưu ý về schema</h2><p>Database bạn cung cấp chỉ có 7 giá trị User.role. Không có SECRETARY. Vì vậy tài khoản <b>Thu Hà</b> được seed bằng role <code>DESK_EDITOR</code> để mô phỏng người xử lý trung gian mà không thay đổi CHECK constraint của bảng User.</p></section>`}
  function auditPage(){return pageHead('Audit Log','Audit là lớp demo frontend, không phải bảng trong schema SQL')+table(['Time','Actor','Role','Action','Entity','ID','Result'],AUDIT.map(a=>`<tr><td>${esc(a.at)}</td><td>${esc(a.actor)}</td><td>${esc(a.role)}</td><td><b>${esc(a.action)}</b></td><td>${esc(a.entity)}</td><td>${esc(a.entity_id)}</td><td>${badge(a.result)}</td></tr>`).join(''),'Chưa có audit. Hãy thao tác workflow để sinh log.')}
  function settings(){return pageHead('Cài đặt','Thiết lập local demo và kiểm thử dữ liệu')+`<div class="grid2"><section class="card"><h2>Giao diện</h2><label class="toggle-row"><span>Dark mode</span><input id="dark-toggle" type="checkbox" ${localStorage.getItem(DARK_KEY)==='1'?'checked':''}></label></section><section class="card"><h2>Dữ liệu</h2><p>Dữ liệu hiện được lưu bằng localStorage. Khi có backend ASP.NET Core/SQL Server, lớp repository/API có thể thay thế store này mà không cần đổi nghiệp vụ.</p><button class="btn danger" data-action="reset">Reset về seed DB</button></section></div>`}

  function render(){const views={dashboard,topics,evaluations,members,estimates,assets,assetRequests,tasks,quotas,extensions,notifications,users,master,account,audit:auditPage,settings};let fn=views[page];let arg; if(page.startsWith('topic-')){fn=topicDetail;arg=Number(page.split('-')[1])} if(!fn)fn=dashboard;document.getElementById('app').innerHTML=shell(fn(arg));bind();}
  function bind(){
    document.querySelectorAll('[data-page]').forEach(x=>x.onclick=()=>{page=x.dataset.page;location.hash=page;render();document.getElementById('sidebar')?.classList.remove('open')});
    document.querySelector('[data-menu]')?.addEventListener('click',()=>document.getElementById('sidebar')?.classList.toggle('open'));
    document.querySelector('[data-search]')?.addEventListener('click',globalSearch);
    document.querySelector('#dark-toggle')?.addEventListener('change',e=>{document.body.classList.toggle('dark',e.target.checked);localStorage.setItem(DARK_KEY,e.target.checked?'1':'0')});
    document.querySelector('#topic-q')?.addEventListener('input',e=>{filters.topics=e.target.value;render()});
    document.querySelector('#topic-status')?.addEventListener('change',e=>{filters.topicStatus=e.target.value;render()});
    document.querySelector('#rq-q')?.addEventListener('input',e=>{filters.requests=e.target.value;render()});
    document.querySelector('#rq-status')?.addEventListener('change',e=>{filters.requestStatus=e.target.value;render()});
    document.querySelector('#task-q')?.addEventListener('input',e=>{filters.tasks=e.target.value;render()});
    document.querySelector('#task-status')?.addEventListener('change',e=>{filters.taskStatus=e.target.value;render()});
    document.querySelector('#user-q')?.addEventListener('input',e=>{filters.users=e.target.value;render()});
    document.querySelector('#notif-q')?.addEventListener('input',e=>{filters.notifications=e.target.value;render()});
    document.querySelectorAll('[data-clear]').forEach(b=>b.onclick=()=>{const k=b.dataset.clear;filters[k]='';filters[k==='topics'?'topicStatus':k==='requests'?'requestStatus':k==='tasks'?'taskStatus':'']='';render()});
    document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>{page='topic-'+b.dataset.topic;location.hash=page;render()});
    document.querySelectorAll('[data-switch-user]').forEach(b=>b.onclick=()=>{accountId=Number(b.dataset.switchUser);persist();toast('Đã chuyển tài khoản: '+user().full_name);page='dashboard';location.hash=page;render()});
    document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>action(b.dataset.action,b.dataset)));
  }
  function globalSearch(){const m=modal('Tìm kiếm nhanh',`<input id="global-q" class="big-input" placeholder="Nhập mã, tiêu đề, tên user, asset..." autofocus><div id="global-results" class="search-results"><p class="muted">Gõ để tìm trên Topic, User, Asset, Task, Request.</p></div>`);const input=m.querySelector('#global-q');const out=m.querySelector('#global-results');input.oninput=()=>{const q=input.value.toLowerCase();if(!q){out.innerHTML='<p class="muted">Gõ để tìm...</p>';return}const results=[];DB.Topic.filter(t=>`${t.title} ${t.topic_code||''}`.toLowerCase().includes(q)).forEach(t=>results.push(`<button data-topic="${t.topic_id}">◆ Topic #${t.topic_id} — ${esc(t.title)}</button>`));DB.User.filter(u=>`${u.full_name} ${u.email}`.toLowerCase().includes(q)).forEach(u=>results.push(`<button data-switch-user="${u.user_id}">♙ User #${u.user_id} — ${esc(u.full_name)}</button>`));DB.Asset.filter(a=>a.asset_name.toLowerCase().includes(q)).forEach(a=>results.push(`<button>▣ Asset #${a.asset_id} — ${esc(a.asset_name)}</button>`));out.innerHTML=results.join('')||'<p class="muted">Không tìm thấy.</p>';out.querySelectorAll('[data-topic]').forEach(x=>x.onclick=()=>{m.closest('.modal-backdrop').remove();page='topic-'+x.dataset.topic;location.hash=page;render()});out.querySelectorAll('[data-switch-user]').forEach(x=>x.onclick=()=>{accountId=Number(x.dataset.switchUser);persist();m.closest('.modal-backdrop').remove();page='dashboard';location.hash=page;render()})}}

  function action(a,d){
    if(a==='new-topic')return newTopicForm();
    if(a==='edit-topic')return newTopicForm(topic(Number(d.id)));
    if(a==='submit-topic')return transition(Number(d.id),'SUBMITTED','Gửi đề tài');
    if(a==='desk-approve')return deskApprove(Number(d.id));
    if(a==='exec-approve')return execApprove(Number(d.id));
    if(a==='request-revision')return transition(Number(d.id),'REVISION_REQUESTED','Yêu cầu chỉnh sửa');
    if(a==='reject-topic')return transition(Number(d.id),'REJECTED','Từ chối');
    if(a==='start-topic')return transition(Number(d.id),'IN_PROGRESS','Bắt đầu tác nghiệp');
    if(a==='deliver-topic')return transition(Number(d.id),'DELIVERED','Bàn giao');
    if(a==='accept-topic')return transition(Number(d.id),'ACCEPTED_READY_FOR_CMS','Chấp nhận / sẵn sàng CMS');
    if(a==='add-member')return memberForm(d.topicId);
    if(a==='add-estimate')return estimateForm(d.topicId);
    if(a==='new-evaluation')return evaluationForm();
    if(a==='new-asset')return assetForm();
    if(a==='new-request')return requestForm(d.topicId);
    if(a==='request-approve')return requestDecision(Number(d.id),'APPROVED');
    if(a==='request-reject')return requestDecision(Number(d.id),'REJECTED');
    if(a==='checkout')return requestDecision(Number(d.id),'CHECKED_OUT');
    if(a==='return-asset')return requestDecision(Number(d.id),'RETURNED');
    if(a==='new-task')return taskForm(d.topicId);
    if(a==='cycle-task')return cycleTask(Number(d.id));
    if(a==='new-quota')return quotaForm();
    if(a==='new-extension')return extensionForm();
    if(a==='extension-approve')return extensionDecision(Number(d.id),'APPROVED');
    if(a==='extension-reject')return extensionDecision(Number(d.id),'REJECTED');
    if(a==='read-notif')return readNotif(Number(d.id));
    if(a==='read-all')return readAll();
    if(a==='new-user')return userForm();
    if(a==='new-desk')return simpleMaster('desk');
    if(a==='new-category')return simpleMaster('category');
    if(a==='new-criteria')return simpleMaster('criteria');
    if(a==='reset'){localStorage.removeItem(KEY);localStorage.removeItem(AUDIT_KEY);location.reload();}
  }
  function transition(id,status,verb){const t=topic(id);if(!t)return;if(status==='SUBMITTED'&&!(can('topic.submit')&&t.author_user_id===user().user_id))return toast('Account hiện tại không được gửi Topic này','error');if(['REVISION_REQUESTED','REJECTED'].includes(status)&&!(can('topic.reviewDesk')||can('topic.reviewExecutive')))return toast('Không có quyền xử lý','error');if(status==='IN_PROGRESS'&&!['APPROVED'].includes(t.status))return toast('Topic phải APPROVED trước khi tác nghiệp','error');if(status==='DELIVERED'&&t.status!=='IN_PROGRESS')return toast('Topic phải IN_PROGRESS trước','error');if(status==='ACCEPTED_READY_FOR_CMS'&&t.status!=='DELIVERED')return toast('Topic phải DELIVERED trước','error');t.status=status;if(status==='APPROVED'&&!t.topic_code)t.topic_code=makeCode(t);audit('STATUS_CHANGE','Topic',id,'SUCCESS',verb+' → '+status);const targets=DB.User.filter(u=>u.user_id!==user().user_id&&([ 'SUBMITTED','PENDING_EXECUTIVE_APPROVAL'].includes(status)?['DESK_EDITOR','EXECUTIVE_EDITOR'].includes(u.role):u.user_id===t.author_user_id));targets.slice(0,3).forEach(u=>notify(u.user_id,id,`Topic #${id}: ${verb} bởi ${user().full_name}.`));persist();toast(`${verb} thành công`);render()}
  function makeCode(t){const d=String(new Date().getFullYear());const deskCode=(desk(cat(t.category_id)?.desk_id)?.desk_name||'NT').split(/\s+/).map(x=>x[0]).join('').slice(0,3).toUpperCase();return `${deskCode}-${d}-${String(t.topic_id).padStart(3,'0')}`}
  function deskApprove(id){const t=topic(id);if(!can('topic.reviewDesk')||t.status!=='SUBMITTED')return toast('Không thể duyệt ở bước phòng','error');t.status='PENDING_EXECUTIVE_APPROVAL';DB.Topic_Evaluation.push({evaluation_id:uid('Topic_Evaluation'),topic_id:id,evaluator_user_id:user().user_id,evaluation_stage:'DESK_REVIEW',decision:'APPROVED',comments:'Duyệt tại Desk.'});DB.Criteria_Config.forEach(c=>DB.Evaluation_Criteria_Score.push({evaluation_id:DB.Topic_Evaluation.at(-1).evaluation_id,criteria_id:c.criteria_id,score:0}));notify(DB.User.find(u=>u.role==='EXECUTIVE_EDITOR')?.user_id,id,`Topic #${id} đã qua Desk và chờ TBT duyệt.`);audit('APPROVE','Topic',id);persist();toast('Đã chuyển Topic sang TBT');render()}
  function execApprove(id){const t=topic(id);if(!can('topic.reviewExecutive')||t.status!=='PENDING_EXECUTIVE_APPROVAL')return toast('Không thể duyệt ở bước TBT','error');t.status='APPROVED';if(!t.topic_code)t.topic_code=makeCode(t);DB.Topic_Evaluation.push({evaluation_id:uid('Topic_Evaluation'),topic_id:id,evaluator_user_id:user().user_id,evaluation_stage:'EXECUTIVE_APPROVAL',decision:'APPROVED',comments:'Tổng biên tập phê duyệt.'});notify(t.author_user_id,id,`Topic #${id} đã được TBT phê duyệt.`);audit('APPROVE','Topic',id);persist();toast('Topic đã APPROVED');render()}
  function requestDecision(id,status){const r=find('Asset_Request',id);if(!r)return;if(['APPROVED','REJECTED'].includes(status)&&!can('asset.requestReview'))return toast('Không có quyền xử lý request','error');if(status==='CHECKED_OUT'&&!(r.requester_user_id===user().user_id))return toast('Chỉ requester được nhận tài sản','error');r.status=status;const asset=find('Asset',r.asset_id);if(asset){if(status==='CHECKED_OUT')asset.asset_status='CHECKED_OUT';if(status==='RETURNED')asset.asset_status='AVAILABLE'}notify(r.requester_user_id,r.topic_id,`Asset Request #${id} đã chuyển sang ${status}.`);audit('STATUS_CHANGE','Asset_Request',id,'SUCCESS',status);persist();toast('Đã cập nhật request');render()}
  function cycleTask(id){const t=find('Fieldwork_Task',id);if(!t)return;if(!(can('task.manage')||t.assignee_user_id===user().user_id))return toast('Không có quyền','error');t.task_status=t.task_status==='TODO'?'IN_PROGRESS':t.task_status==='IN_PROGRESS'?'DONE':'TODO';audit('STATUS_CHANGE','Fieldwork_Task',id,'SUCCESS',t.task_status);persist();toast('Task → '+label(t.task_status));render()}
  function extensionDecision(id,status){const e=find('Request_Deadline_Extension',id);if(!e||!can('extension.review'))return toast('Không có quyền','error');e.status=status;if(status==='APPROVED'){const t=topic(e.topic_id);t.deadline=e.requested_deadline}notify(e.requested_by_user_id,e.topic_id,`Yêu cầu gia hạn #${id} đã ${status==='APPROVED'?'được duyệt':'bị từ chối'}.`);audit('STATUS_CHANGE','Request_Deadline_Extension',id,'SUCCESS',status);persist();toast('Đã xử lý gia hạn');render()}
  function readNotif(id){const n=find('Notification',id);if(n&&n.user_id===user().user_id)n.is_read=1;persist();render()}
  function readAll(){DB.Notification.filter(n=>n.user_id===user().user_id).forEach(n=>n.is_read=1);persist();toast('Đã đánh dấu đã đọc');render()}

  function init(){if(localStorage.getItem(DARK_KEY)==='1')document.body.classList.add('dark');window.addEventListener('hashchange',()=>{page=location.hash.replace('#','')||'dashboard';render()});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();globalSearch()}if(e.key==='Escape')document.getElementById('modal-root')?.remove()});render()}
  init();
})();
